<?php
require_once dirname(dirname(__DIR__)).'/src/bootstrap.php';Auth::requireRole('admin');$errors=[];
if(request_method('POST')){Csrf::verify();$name=trim($_POST['name']??'');$email=strtolower(trim($_POST['email']??''));$phone=normalize_sl_phone($_POST['phone']??'');$district=$_POST['district']??'';$address=trim($_POST['address']??'');$reg=trim($_POST['registration_no']??'');if(strlen($name)<3)$errors[]='Enter hospital name.';if(!filter_var($email,FILTER_VALIDATE_EMAIL))$errors[]='Invalid email.';if(!$phone)$errors[]='Invalid phone.';if(!validate_district($district))$errors[]='Invalid district.';if(strlen($address)<5)$errors[]='Enter hospital address.';if(!$errors){try{$pdo=db();$pdo->beginTransaction();$temp=random_token(16);$pdo->prepare("INSERT INTO users(role,full_name,email,phone,password_hash,status,email_verified_at,phone_verified_at,mfa_enabled) VALUES('hospital',?,?,?,?, 'pending_password',NOW(),NOW(),1)")->execute([$name,$email,$phone,password_hash($temp,PASSWORD_DEFAULT)]);$uid=(int)$pdo->lastInsertId();$pdo->prepare('INSERT INTO hospitals(user_id,name,registration_no,district,address,contact_phone,status,approved_at) VALUES(?,?,?,?,?,?,\'active\',NOW())')->execute([$uid,$name,$reg?:null,$district,$address,$phone]);$hid=(int)$pdo->lastInsertId();$pdo->prepare('UPDATE users SET hospital_id=? WHERE id=?')->execute([$hid,$uid]);foreach(blood_groups() as $g)$pdo->prepare('INSERT INTO blood_inventory(hospital_id,blood_group,units_available) VALUES(?,?,0)')->execute([$hid,$g]);$pdo->commit();$s=$pdo->prepare('SELECT * FROM users WHERE id=?');$s->execute([$uid]);$u=$s->fetch();$dev=(new VerificationService())->createPasswordReset($u,'hospital_invite');if($dev)$_SESSION['dev_hospital_invite_url']=$dev;audit('hospital_created','hospital',$hid,['hospital'=>$name]);flash('success','Hospital created. The primary hospital account can now set its password.');redirect('admin/hospitals.php');}catch(Throwable $e){if(db()->inTransaction())db()->rollBack();$errors[]='Hospital creation failed: '.$e->getMessage();}}}
$rows=db()->query('SELECT h.*,u.email,u.status user_status,(SELECT COUNT(*) FROM users su WHERE su.hospital_id=h.id AND su.role=\'hospital\') staff_count FROM hospitals h JOIN users u ON u.id=h.user_id ORDER BY h.created_at DESC')->fetchAll();$pageTitle='Manage Hospitals';require dirname(dirname(__DIR__)).'/src/templates/header.php';?>
<section class="dashboard"><div class="container"><div class="dash-head"><div><div class="eyebrow">Administration</div><h1>Hospitals</h1></div></div><?=admin_nav()?><?php if(!empty($_SESSION['dev_hospital_invite_url'])):?><div class="flash success"><strong>Local development hospital setup link:</strong> <a href="<?=e((string)$_SESSION['dev_hospital_invite_url'])?>">Open password setup</a></div><?php unset($_SESSION['dev_hospital_invite_url']);endif;?><div class="grid-2"><div class="card"><h2>Add approved hospital</h2><?php if($errors):?><div class="error-list"><?=e(implode(' ',$errors))?></div><?php endif;?><form method="post"><?=Csrf::field()?><div class="field"><label>Hospital name</label><input name="name" required></div><div class="field"><label>Official email</label><input type="email" name="email" required></div><div class="field"><label>Phone</label><input name="phone" placeholder="0771234567" required></div><div class="field"><label>Registration / facility number</label><input name="registration_no"></div><div class="field"><label>District</label><select name="district"><?php foreach(districts() as $d):?><option><?=e($d)?></option><?php endforeach;?></select></div><div class="field"><label>Address</label><textarea name="address" required></textarea></div><button class="btn">Create Hospital</button></form></div><div><h2>Approved hospitals</h2><div class="table-wrap"><table class="table"><thead><tr><th>Hospital</th><th>District</th><th>Primary email</th><th>Staff</th><th>Status</th></tr></thead><tbody><?php if(!$rows):?><tr><td colspan="5" class="empty">No hospitals yet.</td></tr><?php endif;?><?php foreach($rows as $r):?><tr><td><strong><?=e($r['name'])?></strong><br><span class="small"><?=e($r['registration_no']??'No facility number')?></span></td><td><?=e($r['district'])?></td><td><?=e($r['email'])?></td><td><?=e((string)$r['staff_count'])?></td><td><span class="badge <?=$r['status']==='active'?'green':'gray'?>"><?=e($r['status'])?></span></td></tr><?php endforeach;?></tbody></table></div></div></div></div></section>
